							SMI_NUMBER: smiNumber,
							TARGET: "ATTACH_DOC_TEMPLATE"
						}

            			doServiceAjax('sepoa.svc.seal.SepoaReqSealService', 'CONNECTION', 'doSelectCorpAttachDocTemplateFile', {
							DOC_DATA : JSON.stringify(docData)
			            }, function(so) {
			                if (so.status == 1) {
			                	var data = JSON.parse(so.result);
			                	var attachDocFileCheck = data['RESULT'];

			                	if(attachDocFileCheck !== 'ATTACH_DOC_EMPTY'){
									gridObj.cells(id, gridObj.getColIndexById('ATTACH_IMG_TMPLATE')).setIcon('ATTACH_IMG2');
		                    		gridObj.cells(id, gridObj.getColIndexById('ATTACH_IMG_TMPLATE')).cell.children[0].style = 'filter:none';	                	
